update_rule.pseudocode:
if day < mandate_start_day:
  policy_pressure[i] = 0 for all i
  gov_communication = 0
else:
  for each agent i:
    eff_enforcement = enforcement_probability * (1 - compliance_decay_rate)^{day - mandate_start_day}
    policy_pressure[i] = mandate_strength * eff_enforcement * (0.5*trust_in_institutions[i] + 0.5*pro_social_pref[i])
  gov_communication = gov_communication_intensity * mandate_info_multiplier

retailer.stock_level += Poisson(retailer_restock_rate * population_size)
for each agent i:
  if mask_wearing_desired[i,t]==1 and mask_inventory[i]==0:
    affordability = sigmoid(price_elasticity * (retailer.price - mask_cost_mean))
    if retailer.stock_level>0 and budget[i]>=retailer.price and Bernoulli(affordability)==1:
      q = min(max_masks_per_purchase, retailer.stock_level)
      retailer.stock_level -= q
      mask_inventory[i] += q
      budget[i] -= q*retailer.price
    else if share_with_household and any(household member has mask_inventory>0):
      transfer 1 mask to i
  state.mask_wearing[i,t] = 1 if (mask_wearing_desired[i,t]==1 and mask_inventory[i]>0) else 0
adjust retailer.price if desired based on stock (optional rule)
